import type { Chapitre } from '@/lib/chapitre-types'

const SECTIONS: Chapitre['sections'] = [
  {
    numero: '2.1',
    titre: "La formation professionnelle : obligation de l'employeur et politique de l'État",
    navLabel: '2.1 Obligation de formation',
    blocs: [
      { type: 'paragraphe', texte: "Le Titre II du Code du travail, intitulé « De la formation et du perfectionnement professionnels », ne compte que dix articles, mais il pose un principe dont la portée dépasse largement sa brièveté : la formation du travailleur n'est pas laissée à la bonne volonté de l'employeur, elle constitue une obligation légale. Cette obligation s'inscrit dans une politique nationale dont l'État définit les orientations et dont un établissement public spécialisé, l'Institut National de Préparation Professionnelle, assure l'exécution. Le chapitre étudie successivement cette obligation (Titre II, chapitre premier), l'Institut lui-même et son financement (Titre II, chapitre II), puis le contrat d'apprentissage (Titre III), instrument par lequel une personne apprend un métier au sein d'une entreprise." },
      { type: 'filet', titre: "Article 8 du Code du travail", texte: "« Tout employeur public ou privé a l'obligation d'assurer la formation, le perfectionnement ou l'adaptation professionnelle des travailleurs qu'il emploie. A cette fin, il pourra utiliser les moyens mis à sa disposition sur toute l'étendue du territoire de la République Démocratique du Congo par l'Institut National de Préparation Professionnelle. »" },
      { type: 'paragraphe', texte: "Trois observations s'imposent à la lecture de ce texte. La première tient à son champ : l'obligation pèse sur « tout employeur public ou privé », ce qui confirme, après l'article 1er étudié au chapitre 1, que la nature juridique de l'employeur est indifférente. Une entreprise du portefeuille de l'État, une société privée, une ONG ou une confession religieuse employant des travailleurs sont toutes tenues. La deuxième tient à son objet, décrit par trois verbes qui ne sont pas synonymes : la *formation*, qui vise l'acquisition d'une qualification nouvelle ; le *perfectionnement*, qui approfondit une qualification existante ; l'*adaptation*, qui accompagne un changement de poste, de technique ou d'organisation. Un employeur qui introduit un nouveau logiciel de gestion ou une nouvelle machine ne peut pas se contenter d'exiger de ses travailleurs qu'ils s'y conforment : il doit les y adapter. La troisième tient à la nature de l'obligation : c'est une obligation de moyens, non de résultat. L'employeur n'a pas à garantir que chaque travailleur atteindra une qualification donnée ; il doit mettre en œuvre les moyens raisonnables de formation, et le texte lui désigne le principal d'entre eux, les moyens « mis à sa disposition [...] par l'Institut National de Préparation Professionnelle »." },
      { type: 'paragraphe', texte: "Le verbe « pourra » du second alinéa mérite attention. L'employeur *peut* recourir à l'INPP ; il n'y est pas contraint. Il peut satisfaire à son obligation par des formations internes, par un centre de formation agréé, par un organisme étranger ou par la formation à distance. Mais le recours à l'INPP n'est pas gratuit pour autant : comme la section 2.4 le montre, tout employeur finance l'Institut par une cotisation obligatoire, qu'il utilise ou non ses services. L'employeur qui forme ailleurs paie donc deux fois, ce qui explique l'incitation économique forte à recourir aux prestations de l'INPP, en principe accessibles aux cotisants." },
      { type: 'paragraphe', texte: "La sanction de l'obligation de formation est indirecte. Le Titre XV du Code ne prévoit pas de pénalité spécifique pour l'employeur qui ne forme pas. La sanction se manifeste ailleurs : au moment du licenciement pour insuffisance professionnelle, le travailleur pourra faire valoir que son inaptitude résulte du défaut de formation ou d'adaptation de l'employeur, ce qui prive le licenciement de motif valable au sens de l'article 62 (chapitre 4) ; au moment d'un licenciement pour nécessités de fonctionnement lié à une mutation technologique, l'employeur qui n'a pas tenté d'adapter le travailleur s'expose au même reproche. L'obligation de formation est ainsi, en pratique, une composante de l'obligation de bonne foi dans l'exécution du contrat, et un élément d'appréciation du caractère abusif d'une rupture." },
      { type: 'carte', titre: "Articles 9 et 10 du Code du travail", note: "Article 9 : « Un décret du Président de la République, pris sur proposition du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions après avis du Conseil National du Travail, détermine la politique de la formation et du perfectionnement professionnels pour l'emploi et fixe les modalités de fonctionnement des centres de formation professionnelle. » Article 10 : « Le Ministre du Travail et de la Prévoyance Sociale assure l'exécution de la politique de la formation et du perfectionnement professionnels. Il élabore, avec le concours de l'Institut National de Préparation Professionnelle, des Organisations Professionnelles, et, le cas échéant, des centres de formation agréés, le programme de préparation professionnelle visant à promouvoir et à faciliter : la création d'emplois ; l'amélioration de la productivité et le développement économique ; la mobilité professionnelle ; l'insertion professionnelle des jeunes ; la réinsertion des accidentés du travail. »" },
      { type: 'paragraphe', texte: "Ces deux articles organisent la dimension publique de la formation professionnelle. L'article 9 confie la définition de la politique à un décret, pris sur proposition du ministre du Travail et après avis du Conseil National du Travail, organe tripartite étudié au chapitre 8. L'article 10 en confie l'exécution au ministre, assisté de l'INPP, des organisations professionnelles et des centres agréés, et lui assigne cinq finalités qui dessinent une véritable politique de l'emploi : création d'emplois, productivité, mobilité, insertion des jeunes, réinsertion des accidentés du travail. La dernière finalité est remarquable : la formation professionnelle est conçue aussi comme un instrument de réparation, permettant au travailleur devenu inapte à son ancien métier d'en apprendre un autre, ce que l'article 12 appellera la « réadaptation professionnelle des travailleurs frappés d'incapacité professionnelle »." },
      { type: 'paragraphe', texte: "Le texte de l'article 9 illustre en outre l'une des incohérences constitutionnelles relevées par la proposition de loi déposée le 28 mai 2025 par le député Éric Tshikuma (chapitre 1, section 1.10) : il renvoie à « un décret du Président de la République », formule héritée de la période de transition antérieure à la Constitution du 18 février 2006, alors que celle-ci confie au Premier ministre le pouvoir réglementaire d'exécution des lois. En pratique, les décrets d'application du Code sont pris par le Premier ministre, comme le décret n°25/22 du 30 mai 2025 sur le SMIG ; la lettre du Code n'a pas été mise à jour. L'étudiant doit lire « décret du Président de la République » comme désignant, dans l'ordre constitutionnel actuel, le décret du Premier ministre délibéré en Conseil des ministres." },
      { type: 'paragraphe', texte: "L'organisation administrative de la formation professionnelle a par ailleurs évolué depuis 2002. Le Code de 2002 ne connaît qu'un ministre, celui du Travail et de la Prévoyance sociale. Or, un ministère distinct de la Formation professionnelle et des Métiers a été institué au sein du Gouvernement ; il a reçu le 16 avril 2026 le nouveau cadre organique de son Secrétariat général, au terme de huit mois de travaux techniques engagés en 2025, avec pour objectifs de renforcer la gouvernance administrative, de maîtriser les effectifs et la paie et de rationaliser les structures. Ce ministère a lancé, le 25 février 2026, une formation de deux cents agents à l'approche par compétences, a fait valider, lors de la Semaine de la formation professionnelle tenue du 15 au 19 décembre 2025 avec la coopération belge Enabel, un annuaire national d'identification des filières prioritaires pour le développement local, et a engagé avec le ministère de l'Éducation nationale la création de passerelles entre les filières de l'enseignement général et de la formation professionnelle, dont la mise en œuvre est annoncée pour l'année scolaire 2026-2027. La répartition des compétences entre ce ministère et celui de l'Emploi et du Travail, qui conserve la tutelle technique de l'INPP en vertu de l'article 14, relève des ordonnances fixant les attributions des ministères, et non du Code : c'est un exemple de la nécessité, signalée au chapitre 1, de lire le Code avec ses textes d'organisation administrative." },
    ],
  },
  {
    numero: '2.2',
    titre: "L'Institut National de Préparation Professionnelle : création, nature juridique et missions",
    navLabel: "2.2 L'INPP : statut et missions",
    blocs: [
      { type: 'paragraphe', texte: "Le chapitre II du Titre II est consacré à l'Institut National de Préparation Professionnelle, « I.N.P.P. en sigle ». L'Institut est antérieur au Code : il a été créé par l'ordonnance-loi n°206 du 29 juin 1964, à laquelle l'article 17 renvoie encore, ce qui en fait l'une des plus anciennes institutions du droit du travail congolais, contemporaine des premières années de l'indépendance. Le Code de 2002 le consacre, en définit les missions et en organise la gouvernance et le financement." },
      { type: 'filet', titre: "Article 11 du Code du travail", texte: "« Il est institué un Institut National de Préparation Professionnelle, I.N.P.P. en sigle, doté de la personnalité juridique. Son siège est établi à Kinshasa. Il possède notamment la capacité d'acquérir des biens meubles et immeubles et d'en disposer. Ses engagements sont garantis par l'Etat. »" },
      { type: 'paragraphe', texte: "La personnalité juridique de l'Institut lui permet d'être titulaire de droits et d'obligations distincts de ceux de l'État : il peut contracter, acquérir et aliéner des biens, agir en justice, employer du personnel. La garantie de l'État sur ses engagements rassure ses cocontractants et ses créanciers, mais elle traduit aussi le contrôle étroit qu'exerce la puissance publique sur un organisme dont les ressources proviennent essentiellement d'une cotisation obligatoire. La nature juridique précise de l'Institut a varié avec le droit des entreprises publiques : constitué en entreprise publique par l'ordonnance n°78-188 du 5 mai 1978 portant ses statuts, il a été transformé, à la suite de la loi n°08/009 du 7 juillet 2008 portant dispositions générales applicables aux établissements publics, en établissement public à caractère technique et social, doté de la personnalité juridique et de l'autonomie administrative et financière, par le décret n°09/55 du 3 décembre 2009 fixant ses statuts. Ces textes, qui figurent dans les visas de l'arrêté interministériel du 24 septembre 2025 étudié à la section 2.4, sont ceux qu'il faut consulter pour toute question d'organisation interne de l'Institut." },
      { type: 'carte', titre: "Article 12 du Code du travail", note: "« L'Institut, par association des intérêts et des responsabilités de l'Etat, des employeurs et des travailleurs, est chargé de collaborer à la promotion, à la création et à la mise en application des moyens existants ou nouveaux, nécessaires pour la qualification professionnelle de la population active nationale et à la coordination de leur fonctionnement. Son action est notamment destinée au perfectionnement et à la promotion professionnelle des travailleurs dans l'emploi, à la formation rapide de nouveaux travailleurs dans l'emploi, à la formation rapide de nouveaux travailleurs adultes, à l'apprentissage dans l'emploi, à la préparation professionnelle des bénéficiaires d'une culture générale de base, et à l'adaptation professionnelle de ceux ayant reçu une formation technique ou professionnelle de type scolaire. Son action tendra également à faciliter la conversion de la qualification professionnelle des travailleurs devant changer de profession ou de métier et la réadaptation professionnelle des travailleurs frappés d'incapacité professionnelle. »" },
      { type: 'paragraphe', texte: "La mission générale de l'Institut est définie par une formule dont la structure tripartite est essentielle : il agit « par association des intérêts et des responsabilités de l'Etat, des employeurs et des travailleurs ». L'INPP n'est pas un service administratif de l'État ; c'est un organisme paritaire élargi, où les partenaires sociaux qui le financent participent à sa gouvernance. Sa mission couvre l'ensemble du cycle de la qualification professionnelle : le perfectionnement des travailleurs déjà en emploi, la formation rapide de nouveaux travailleurs (y compris adultes), l'apprentissage dans l'emploi, la préparation professionnelle des jeunes n'ayant qu'une culture générale de base, l'adaptation de ceux qui sortent de l'enseignement technique, la reconversion de ceux qui doivent changer de métier et la réadaptation de ceux qui ont perdu leur capacité professionnelle. L'Institut publie chaque année un catalogue de formations continues, organisé par filières (mécanique, électricité, bâtiment, hôtellerie, informatique, gestion), et dispose de centres dans plusieurs provinces." },
      { type: 'carte', titre: "Article 13 du Code du travail : les missions complémentaires", note: "« L'Institut National de Préparation Professionnelle est chargé en outre : a) de créer et de maintenir la coopération entre tous les organismes s'occupant de formation technique et professionnelle, notamment en établissant et en distribuant toutes informations utiles sur les possibilités de formation pour chaque profession ; b) de collaborer à la désignation des professions pour lesquelles des normes de qualification sont considérées comme nécessaires ou souhaitables, à l'établissement de ces normes, à la détermination de la nature et du degré des qualifications professionnelles et à l'organisation des examens destinés à les sanctionner ; c) de coopérer avec les services publics et les organisations professionnelles intéressées à l'établissement d'une classification professionnelle et à la détermination des qualifications professionnelles pour chaque niveau d'emploi, pour chaque métier ou chaque profession ; d) d'apporter le fruit de son expérience à la Direction de l'Emploi et à l'Office National de l'Emploi sur les problèmes d'étude des tendances du marché de l'emploi, de l'évaluation des besoins actuels et futurs des travailleurs des différents niveaux de la classification professionnelle et du placement des travailleurs ; e) de promouvoir le système adéquat d'orientation et de sélection professionnelle et de participer à son fonctionnement ; f) de collaborer avec le Ministère de l'Éducation Nationale et avec toutes les organisations professionnelles ou culturelles intéressées aux activités de préparation professionnelle. »" },
      { type: 'paragraphe', texte: "Ces six missions complémentaires font de l'INPP le pivot technique du marché du travail congolais. Deux d'entre elles ont des conséquences juridiques directes pour les employeurs. La mission b) fait de l'Institut l'organisme de certification des qualifications : les « normes de qualification », les « examens destinés à les sanctionner » et le certificat de fin d'apprentissage (art. 24, point 6) sont les instruments par lesquels un métier acquiert une reconnaissance officielle. La mission c) concerne la classification professionnelle, c'est-à-dire la hiérarchie des emplois (manœuvre ordinaire, manœuvre spécialisé, ouvrier, agent de maîtrise, cadre de collaboration) qui sert de base au barème du SMIG et à la « tension salariale » de un à dix maintenue par le décret n°25/22 du 30 mai 2025 entre le manœuvre ordinaire et le cadre de collaboration. La mission d) organise la coopération avec l'Office National de l'Emploi, dont le visa conditionne la validité des contrats d'apprentissage (art. 21) et des contrats de travail écrits (art. 47) ; la mission f) lie l'Institut au ministère de l'Éducation nationale, ce que traduisent les passerelles annoncées pour 2026-2027." },
      { type: 'paragraphe', texte: "L'actualité récente illustre cette fonction de pivot. Le 23 décembre 2025, l'Association nationale des établissements publics et entreprises du Portefeuille (ANEP) et l'INPP ont signé un protocole d'accord destiné à adapter l'offre de formation aux besoins réels du marché du travail, à renforcer la compétitivité des entreprises du portefeuille et l'employabilité de leurs travailleurs, et à aider l'Institut à mobiliser les ressources nécessaires, dans le cadre de l'objectif gouvernemental de création de six millions d'emplois. Le même mois, une conférence sino-congolaise sur la formation professionnelle, tenue le 22 décembre 2025, a annoncé le déploiement de dispositifs de formation mobiles à partir d'avril 2026. Les institutions publiques de l'emploi et de la formation professionnelle ont en outre signé un contrat-programme de performance pour l'exercice 2026, visant la gouvernance, l'employabilité et la synergie entre formation et insertion professionnelle. Ces initiatives relèvent de la politique publique et des conventions entre organismes ; elles ne créent pas d'obligations nouvelles à la charge des employeurs privés, mais elles orientent l'usage des ressources que ceux-ci versent à l'Institut." },
    ],
  },
  {
    numero: '2.3',
    titre: "Gouvernance tripartite et tutelle de l'État",
    navLabel: '2.3 Gouvernance et tutelle',
    blocs: [
      { type: 'filet', titre: "Article 14 du Code du travail", texte: "« La tutelle technique de l'Etat sur l'Institut National de Préparation Professionnelle est exercée par le Ministère ayant le Travail et la Prévoyance Sociale dans ses attributions. L'organisation générale, l'administration et la gestion de l'Institut sont assumées par un Conseil d'Administration de forme tripartite associant les représentants de l'Etat, des employeurs et des travailleurs. »" },
      { type: 'paragraphe', texte: "L'article 14 distingue deux niveaux. Le premier est la tutelle : l'Institut est un organisme autonome, mais placé sous la tutelle technique du ministère ayant le Travail dans ses attributions. La tutelle n'est pas la hiérarchie : le ministre ne dirige pas l'Institut, il en contrôle les actes les plus importants (budget, programme, nominations, marchés) et veille à la conformité de son action à la politique nationale définie en vertu de l'article 9. La loi n°08/009 du 7 juillet 2008 sur les établissements publics organise en outre une tutelle financière, exercée par le ministre des Finances, ce qui explique que l'arrêté fixant le taux de cotisation soit conjoint aux ministres du Travail, des Finances et du Budget. Le second niveau est la gestion : elle appartient à un Conseil d'administration « de forme tripartite », où siègent des représentants de l'État, des employeurs et des travailleurs. Cette composition est la conséquence logique de l'article 12 (« association des intérêts et des responsabilités ») et du mode de financement : ceux qui paient la cotisation participent aux décisions sur son emploi." },
      { type: 'paragraphe', texte: "Le tripartisme est un principe structurant du droit du travail congolais, que l'on retrouve au Conseil National du Travail (Titre XI), dans la gouvernance de la Caisse nationale de sécurité sociale et dans celle de l'Office National de l'Emploi. Il traduit en droit interne le principe fondateur de l'Organisation internationale du Travail, seule organisation du système des Nations unies où les gouvernements, les employeurs et les travailleurs disposent chacun d'une voix. Pour l'INPP, le tripartisme a une portée pratique : les représentants des employeurs, désignés par les organisations professionnelles les plus représentatives (la Fédération des entreprises du Congo pour le secteur privé, l'ANEP pour le portefeuille de l'État), peuvent orienter l'offre de formation vers les besoins réels des entreprises, ce qui est précisément l'objet du protocole ANEP-INPP de décembre 2025." },
      { type: 'tableau', tableau: { entetes: ['Organe ou autorité', 'Rôle', 'Fondement'], lignes: [
        ["Ministère ayant le Travail dans ses attributions (aujourd'hui Emploi et Travail)", "Tutelle technique ; exécution de la politique de formation ; proposition du décret de politique", "Art. 9, 10 et 14"],
        ["Ministères des Finances et du Budget", "Tutelle financière ; co-signature de l'arrêté fixant le taux de cotisation", "Art. 15 ; loi n°08/009"],
        ["Conseil National du Travail", "Avis préalable sur le décret de politique et sur le taux de cotisation", "Art. 9 et 15"],
        ["Conseil d'administration tripartite de l'INPP", "Organisation générale, administration et gestion", "Art. 14 ; décret n°09/55"],
        ["Ministère de la Formation professionnelle et des Métiers", "Politique sectorielle de la formation professionnelle, centres agréés, passerelles avec l'éducation", "Ordonnances fixant les attributions des ministères"],
      ] } },
      { type: 'paragraphe', texte: "L'existence d'un ministère de la Formation professionnelle distinct de celui de l'Emploi et du Travail, non prévue par le Code, pose une question de coordination que les textes d'organisation gouvernementale règlent par la répartition des attributions. La lecture combinée des articles 9, 10 et 14 conduit à distinguer la politique générale de la formation « pour l'emploi », qui reste rattachée au Travail et à l'INPP, et la formation professionnelle initiale et par les métiers, dont le ministère spécialisé assure l'organisation, notamment par l'agrément et le contrôle des centres de formation et par l'articulation avec l'enseignement technique. Le praticien qui doit identifier l'autorité compétente pour un agrément, une subvention ou un programme vérifiera l'ordonnance fixant les attributions des ministères en vigueur à la date des faits." },
    ],
  },
  {
    numero: '2.4',
    titre: "Le financement de l'INPP : la cotisation patronale",
    navLabel: '2.4 La cotisation INPP',
    blocs: [
      { type: 'carte', titre: "Article 15 du Code du travail", note: "« Les ressources de l'Institut National de Préparation Professionnelle sont constituées par : a) la subvention annuelle de l'Etat ; b) la cotisation mensuelle des employeurs proportionnelle à la somme des rémunérations versées par eux à leur personnel au cours du trimestre précédent ; Le taux de cette cotisation est fixé pour chaque période de 3 ans par arrêté conjoint des Ministres ayant respectivement le Travail et la Prévoyance Sociale, les Finances et le Budget dans leurs attributions après avis du Conseil National du Travail. A défaut d'avis conforme, le taux de la cotisation est fixé par décret du Président de la République pris sur proposition des Ministres ayant respectivement le Travail et la Prévoyance sociale, les Finances et le Budget dans leurs attributions. c) des apports, dons et legs qui pourront lui être consentis ; d) des rétributions exceptionnelles pour services spéciaux et notamment pour la fourniture du matériel didactique, fixées conventionnellement par l'Institut et les employeurs. »" },
      { type: 'paragraphe', texte: "L'article 15 énumère quatre ressources, mais l'une d'elles domine toutes les autres : la cotisation patronale. La subvention de l'État est annuelle et, en pratique, modeste ; les dons et legs sont exceptionnels ; les rétributions pour services spéciaux (fourniture de matériel didactique, formations sur mesure) sont conventionnelles. La cotisation, elle, est obligatoire, mensuelle et « proportionnelle à la somme des rémunérations versées ». Elle relève de la parafiscalité sociale : c'est un prélèvement obligatoire, assis sur la masse salariale, affecté à un établissement public distinct du Trésor. Elle se distingue de l'impôt sur les rémunérations, retenu à la source sur le travailleur au profit de l'État, et des cotisations de sécurité sociale, versées à la CNSS. La cotisation INPP est à la charge exclusive de l'employeur : aucune part n'est retenue sur le salaire du travailleur." },
      { type: 'paragraphe', texte: "L'assiette de la cotisation est « la somme des rémunérations versées ». Le mot rémunération renvoie à la définition de l'article 7, point 8, étudiée au chapitre 1 : salaire, commissions, primes, gratifications, heures supplémentaires, avantages en nature et allocation de congé y entrent ; les soins de santé, l'indemnité de logement, les allocations familiales légales, l'indemnité de transport et les frais de voyage en sont exclus. L'assiette de la cotisation INPP est donc la même que celle des cotisations de sécurité sociale, et non l'assiette fiscale de l'impôt sur les revenus des personnes physiques, qui obéit à ses propres règles de déduction. Le texte précise que la cotisation mensuelle est calculée sur les rémunérations « versées [...] au cours du trimestre précédent », formule qui organise un décalage entre la période de référence et le paiement ; l'ordonnance n°84/186 du 15 octobre 1984 fixe les modalités pratiques de paiement." },
      { type: 'paragraphe', texte: "Le taux n'est pas fixé par le Code, mais par un arrêté conjoint des ministres du Travail, des Finances et du Budget, « pour chaque période de 3 ans », après avis du Conseil National du Travail ; à défaut d'avis conforme, un décret tranche. La périodicité triennale n'a pas été respectée en pratique : le taux fixé par l'arrêté interministériel du 14 février 2006 est resté en vigueur près de vingt ans, jusqu'à l'arrêté interministériel du 24 septembre 2025, pris après que le Conseil National du Travail eut été entendu en sa trente-septième session ordinaire, tenue du 25 au 29 avril 2025. Ce nouvel arrêté abroge celui de 2006 et « entre en vigueur à la date de sa signature ». Il a lui-même été précédé d'un arrêté du 28 mars 2003, abrogé en 2006, dont le taux n'est pas connu avec certitude et ne doit pas être reconstitué de mémoire." },
      { type: 'carte', titre: "Arrêté interministériel du 24 septembre 2025, article 1er", note: "« Le taux de la cotisation mensuelle due à l'Institut National de Préparation Professionnelle, par chaque employeur, sur les rémunérations versées à ses travailleurs est fixé à : 1° pour les entreprises et établissements publics : 4 % ; 2° pour les entreprises et établissements privés : a) occupant entre 1 à 50 travailleurs : 3,5 % ; b) occupant de 51 à 300 travailleurs : 3 % ; c) occupant plus de 300 travailleurs : 2 %. » Article 2 : « Sont abrogés l'Arrêté Interministériel n° 12/MTPS/123, n° 007/CAB/MIN/FINANCES/2006, n° 001/CAB/MIN/BUD/2006 du 14 février 2006 [...] ainsi que toutes les dispositions antérieures contraires au présent Arrêté. » Signé à Kinshasa par le Vice-Premier ministre, ministre du Budget, le ministre des Finances et le ministre de l'Emploi et Travail." },
      { type: 'tableau', tableau: { entetes: ["Catégorie d'employeur", "Taux 2006 (abrogé)", "Taux depuis le 24 septembre 2025"], lignes: [
        ["Entreprises et établissements publics", "3 %", "4 %"],
        ["Privés occupant 1 à 50 travailleurs", "3 %", "3,5 %"],
        ["Privés occupant 51 à 300 travailleurs", "2 %", "3 %"],
        ["Privés occupant plus de 300 travailleurs", "1 %", "2 %"],
      ] } },
      { type: 'paragraphe', texte: "Deux critères commandent le taux, dans cet ordre : la nature de l'employeur (public ou privé), puis, pour le privé seulement, l'effectif occupé. Jamais le chiffre d'affaires, jamais la masse salariale globale. La dégressivité selon l'effectif est un choix de politique économique : les petites entreprises, qui forment peu en interne et recourent davantage aux services de l'Institut, contribuent à un taux plus élevé ; les grandes, qui disposent souvent de leurs propres centres de formation, contribuent à un taux plus faible. La réforme de 2025 relève tous les taux et resserre l'écart entre la plus petite et la plus grande tranche du secteur privé, de deux points en 2006 à un point et demi en 2025. Les considérants de l'arrêté justifient ce relèvement par « l'accroissement des besoins de formation en provenance du monde de travail au regard de l'évolution technique et technologique » et par la nécessité de doter l'Institut « des moyens requis pour renforcer ses capacités institutionnelles et humaines »." },
      { type: 'carte', titre: "Exemple chiffré : une société privée de 120 travailleurs", texte: "Masse mensuelle des rémunérations au sens de l'article 7 : 48 000 000 FC (salaires, primes et heures supplémentaires), auxquels s'ajoutent 6 000 000 FC d'indemnités de logement et 2 400 000 FC d'indemnités de transport, hors assiette. Cotisation INPP : 48 000 000 × 3 % = 1 440 000 FC par mois depuis le 24 septembre 2025 ; elle était de 48 000 000 × 2 % = 960 000 FC sous l'arrêté de 2006. Si la société était un établissement public, le taux serait de 4 %, soit 1 920 000 FC. Si elle n'occupait que 45 travailleurs, le taux serait de 3,5 %. La date du versement des rémunérations commande le taux applicable : les rémunérations versées avant le 24 septembre 2025 restent soumises à l'ancien barème.", note: "En comptabilité SYSCOHADA, la charge est constatée dans les charges de personnel (classe 6, charges sociales) et la dette envers l'Institut au compte 4331, jusqu'au paiement." },
      { type: 'filet', titre: "Article 16 du Code du travail", texte: "« Le relevé des sommes dues à l'Institut National de Préparation Professionnelle au titre des cotisations prévues à l'article précédent, certifié par le Ministre du Travail et de la Prévoyance Sociale ou son délégué, vaut titre permettant les saisies prévues par les articles 106 et suivants du Code de procédure civile. »" },
      { type: 'paragraphe', texte: "Le recouvrement de la cotisation bénéficie d'un privilège procédural considérable : le relevé des sommes dues, une fois certifié par le ministre ou son délégué, « vaut titre permettant les saisies ». L'Institut n'a donc pas besoin d'obtenir un jugement de condamnation contre l'employeur défaillant ; le relevé certifié est un titre exécutoire administratif, sur le fondement duquel les saisies du Code de procédure civile peuvent être pratiquées. Ce mécanisme, comparable à celui dont bénéficient l'administration fiscale et la CNSS, explique que le contentieux de la cotisation INPP soit un contentieux de l'opposition à exécution, où l'employeur conteste après coup le montant réclamé, plutôt qu'un contentieux de la condamnation. L'article 17 complète le dispositif en maintenant en vigueur « toutes les dispositions de l'ordonnance-loi n°206 du 29 juin 1964 [...] et des textes pris pour son application qui ne sont pas contraires aux dispositions du présent titre » : là encore, le Code de 2002 s'appuie sur la législation antérieure plutôt que de la remplacer intégralement." },
      { type: 'controle', question: {
        id: 'ctrl-2-4', question: "Une entreprise privée de 280 travailleurs a versé en octobre 2025 des rémunérations (au sens de l'article 7) de 90 000 000 FC et des indemnités de logement de 12 000 000 FC. Quel est le montant de sa cotisation INPP ?",
        options: [
          { id: 'a', texte: "90 000 000 × 2 % = 1 800 000 FC" },
          { id: 'b', texte: "90 000 000 × 3 % = 2 700 000 FC" },
          { id: 'c', texte: "102 000 000 × 3 % = 3 060 000 FC" },
          { id: 'd', texte: "90 000 000 × 3,5 % = 3 150 000 FC" },
          { id: 'e', texte: "90 000 000 × 4 % = 3 600 000 FC" },
        ],
        reponseCorrecte: 'b', articleRef: "Art. 15 ; arrêté du 24 septembre 2025",
        explication: "Entreprise privée occupant de 51 à 300 travailleurs : 3 % depuis le 24 septembre 2025 (2 % sous l'arrêté de 2006). L'assiette est la rémunération au sens de l'article 7, dont l'indemnité de logement est exclue.",
      } },
    ],
  },
  {
    numero: '2.5',
    titre: "Le contrat d'apprentissage : notion et conditions de fond",
    navLabel: "2.5 Apprentissage : notion",
    blocs: [
      { type: 'paragraphe', texte: "Le Titre III du Code (art. 18 à 35) organise le contrat d'apprentissage, défini à l'article 7, point 7, comme « le contrat par lequel une personne physique ou morale, le maître d'apprentissage, s'oblige à donner ou à faire donner une formation professionnelle méthodique et complète à une personne, l'apprenti, et par lequel ce dernier s'oblige en retour à se conformer aux instructions qu'il recevra et à exécuter les ouvrages qui lui seront confiés en vue de son apprentissage ». Cette définition révèle la nature du contrat : c'est un contrat synallagmatique dont l'objet principal est la formation, et non la production. L'apprenti travaille, mais « en vue de son apprentissage » ; le maître reçoit son travail, mais en contrepartie d'une obligation d'enseigner. Cette finalité distingue l'apprentissage du contrat de travail, où le travail est fourni contre rémunération, et du stage, qui n'est pas réglementé par le Code et n'oblige pas à une formation méthodique et complète." },
      { type: 'paragraphe', texte: "Le contrat d'apprentissage répond à une réalité économique majeure en RDC : l'apprentissage « sur le tas » dans les ateliers de mécanique, de couture, de menuiserie, de coiffure ou de construction est le mode de formation professionnelle le plus répandu, bien avant l'enseignement technique et les centres agréés. Le Titre III vise à encadrer cette pratique, à protéger l'apprenti, souvent mineur, contre l'exploitation d'un travail productif gratuit déguisé en formation, et à garantir la qualité de l'enseignement dispensé. Le législateur y parvient par une série de conditions de fond, de forme et de contrôle, dont la clé de voûte est le visa de l'Office National de l'Emploi." },
      { type: 'filet', titre: "Article 18 du Code du travail", texte: "« Nul ne peut recevoir des apprentis mineurs s'il n'est : âgé de 18 ans au moins ; reconnu de bonne vie et mœurs ; suffisamment qualifié pour donner aux apprentis une formation appropriée ou faire donner cette formation par une autre personne à son service ayant les qualités requises. Aucun maître, s'il ne vit en famille ou en communauté, ne peut loger comme apprenties des jeunes filles mineures. »" },
      { type: 'paragraphe', texte: "Les conditions de l'article 18 s'imposent au maître qui reçoit des apprentis *mineurs* ; pour les apprentis majeurs, le Code ne pose pas de condition expresse, mais l'exigence de qualification du maître découle de la définition même du contrat, qui suppose une formation « méthodique et complète ». Le maître doit d'abord avoir dix-huit ans au moins : un apprenti devenu compagnon à dix-sept ans ne peut recevoir d'apprentis à son tour. Il doit ensuite être « reconnu de bonne vie et mœurs », condition d'honorabilité qui s'apprécie au regard des antécédents judiciaires et de la réputation, et qui s'explique par l'autorité que le maître exerce sur un mineur, parfois logé chez lui. Il doit enfin être « suffisamment qualifié », personnellement ou par l'intermédiaire d'une personne à son service : une société peut être maître d'apprentissage (l'article 7 vise « une personne physique ou morale ») dès lors qu'elle dispose de formateurs qualifiés. Le second alinéa ajoute une règle de protection des jeunes filles mineures : le maître qui ne vit pas « en famille ou en communauté » ne peut les loger. L'article 29, point d), en tirera une conséquence sur la fin du contrat." },
      { type: 'paragraphe', texte: "Du côté de l'apprenti, la condition essentielle est la capacité, régie par l'article 6 étudié au chapitre 1. L'apprenti a en principe dix-huit ans ; il peut avoir de seize à dix-huit ans pour des travaux légers et salubres ; il peut avoir quinze ans, « même comme apprenti[…] », sur dérogation expresse du Président du Tribunal de paix après avis psycho-médical d'un expert et de l'inspecteur du travail. En dessous de quinze ans, aucun apprentissage n'est possible, quelle que soit la volonté des parents. L'article 22, point c), ajoute une condition d'aptitude négative : l'autorité qui vise le contrat doit s'assurer que l'apprenti « n'a pas fait des études ou subi une préparation spécialisée constituant présomption de capacité professionnelle exclusive d'apprentissage ». Un diplômé de l'enseignement technique en mécanique ne peut pas être engagé comme « apprenti mécanicien » : sa qualification est présumée acquise, et le contrat d'apprentissage ne servirait qu'à éluder le contrat de travail et le salaire qui lui est dû." },
      { type: 'tableau', tableau: { entetes: ['Condition', "Maître d'apprentissage", 'Apprenti'], lignes: [
        ["Âge", "18 ans au moins pour recevoir des apprentis mineurs (art. 18)", "18 ans ; 16 à 18 ans pour travaux légers ; 15 ans sur dérogation judiciaire (art. 6)"],
        ["Honorabilité", "Bonne vie et mœurs (art. 18)", "Sans objet"],
        ["Qualification", "Suffisante, personnellement ou par un préposé qualifié (art. 18)", "Absence de qualification déjà acquise dans le métier (art. 22, c)"],
        ["Aptitude physique", "Sans objet", "Certificat médical de moins de trois mois (art. 22, a)"],
        ["Liberté d'engagement", "Sans objet", "Libre de tout engagement antérieur (art. 22, c)"],
        ["Logement", "Interdiction de loger des jeunes filles mineures hors vie en famille ou en communauté (art. 18)", "Sans objet"],
      ] } },
    ],
  },
  {
    numero: '2.6',
    titre: "Forme, mentions obligatoires et visa du contrat d'apprentissage",
    navLabel: '2.6 Forme et visa',
    blocs: [
      { type: 'filet', titre: "Article 19 du Code du travail", texte: "« Tout contrat d'apprentissage doit être constaté par écrit et contenir les mentions énumérées à l'article 20 du présent Code. Il est rédigé en langue officielle ou nationale connue de l'apprenti. Il est signé par le maître, l'apprenti et les parents, à défaut de ceux-ci par le tuteur ou la personne autorisée par les parents ou encore le juge compétent. Il est exempt de tout droit de timbre et d'enregistrement. »" },
      { type: 'paragraphe', texte: "À la différence du contrat de travail, qui « peut être écrite ou verbale » (art. 7, point 3), le contrat d'apprentissage « doit être constaté par écrit ». L'écrit n'est pas seulement un mode de preuve : c'est une condition de validité, dont l'absence entraîne la présomption de contrat de travail organisée par l'article 23. La langue du contrat doit être « officielle ou nationale connue de l'apprenti » : le français, langue officielle, ou l'une des quatre langues nationales (kikongo, lingala, swahili, tshiluba), à condition que l'apprenti la comprenne, ce qui garantit un consentement éclairé. Le contrat est signé par trois parties au moins : le maître, l'apprenti et ses parents, remplacés à défaut par le tuteur, la personne autorisée par les parents ou le juge compétent. La signature des parents n'est pas une simple formalité : elle engage l'autorité parentale, qui sera avertie en cas de maladie, d'absence ou de faute grave (art. 24, point 3) et qui pourra demander la résiliation. L'exemption de droits de timbre et d'enregistrement a une finalité sociale : ne pas décourager la formalisation par un coût fiscal." },
      { type: 'carte', titre: "Article 20 du Code du travail : les mentions obligatoires", note: "« Le contrat d'apprentissage est établi en tenant compte des usages et coutumes de la profession. Il doit faire obligatoirement mention : 1) des prénoms, noms, post-noms, âge, profession, nationalité et domicile du maître, de l'adresse et de la raison sociale de l'entreprise ou du service public qui engage l'apprenti ; 2) des prénoms, noms, post-noms, âge, profession, nationalité et domicile de l'apprenti ; 3) des prénoms, noms, post-noms, âge, profession, nationalité et domicile du père et de la mère de l'apprenti, de son tuteur ou à leur défaut, de la personne autorisée par les parents ou du juge compétent ; 4) de la date du début et de la durée du contrat ; cette dernière est fixée conformément aux usages de la profession, mais ne peut excéder quatre ans ; 5) des indemnités en espèces éventuellement consenties ; 6) de l'indication de la profession ou du métier enseigné ainsi que de l'indication des cours professionnels que le maître s'engage à faire suivre à l'apprenti, soit dans l'établissement, soit au dehors. »" },
      { type: 'paragraphe', texte: "Six mentions sont obligatoires. Les trois premières identifient les parties, y compris les représentants légaux de l'apprenti, avec un luxe de précisions (post-noms, âge, nationalité, domicile) qui vise à rendre le contrat vérifiable par l'autorité de visa. La quatrième fixe la date de début et la durée, plafonnée à quatre ans : au-delà, la « formation » cesse d'être crédible et le contrat masque un emploi. La durée effective dépend des « usages de la profession » : elle est plus courte pour la coiffure que pour la mécanique automobile ou la maçonnerie. La cinquième mention porte sur « les indemnités en espèces éventuellement consenties » ; le mot « éventuellement » ne signifie pas que l'apprenti puisse ne rien recevoir, puisque l'article 25 impose une rémunération sous forme d'indemnité, mais que le montant est fixé au contrat dans les conditions réglementaires. La sixième mention est la plus importante pour la qualification du contrat : le métier enseigné et « les cours professionnels que le maître s'engage à faire suivre à l'apprenti, soit dans l'établissement, soit au dehors ». C'est cette obligation de cours qui distingue l'apprentissage véritable, alternant pratique et enseignement, de l'exploitation d'une main-d'œuvre juvénile." },
      { type: 'carte', titre: "Articles 21 et 22 du Code du travail : le visa de l'ONEM", note: "Article 21 : « Le contrat d'apprentissage est rédigé en quatre exemplaires au moins et soumis au visa de l'Office National de l'Emploi, tel qu'institué au Titre IX du présent Code. La demande de visa incombe au maître. Tant que le contrat n'a pas été soumis au visa, ou lorsque le visa a été retiré, les services de l'apprenti sont présumés être prestés en exécution d'un contrat de travail respectivement à la date de la conclusion du contrat et du retrait du visa. » Article 22 : « L'autorité qui vise le contrat doit : a) exiger la production par le maître d'un certificat médical, datant de moins de trois mois, déclarant le futur apprenti apte aux travaux de la profession ou du métier choisi et établi dans les conditions fixées par l'arrêté prévu à l'article 38 du présent Code ; b) constater l'identité de l'apprenti et la conformité du contrat aux dispositions du présent Code et des textes pris pour son application ; c) s'assurer que l'apprenti est libre de tout engagement antérieur, n'a pas fait des études ou subi une préparation spécialisée constituant présomption de capacité professionnelle exclusive d'apprentissage ; d) remettre après avis, un exemplaire du contrat à chacune des parties et pour l'apprenti mineur, à son représentant, en conserver le troisième et adresser le quatrième à l'Inspecteur du Travail du ressort. »" },
      { type: 'paragraphe', texte: "Le visa de l'Office National de l'Emploi est la pièce maîtresse du dispositif. La demande incombe au maître, et non à l'apprenti ni à ses parents : c'est sur l'employeur que pèse la charge de la formalisation, et c'est lui qui en supporte la sanction. Cette sanction est originale : tant que le contrat n'a pas été soumis au visa, « les services de l'apprenti sont présumés être prestés en exécution d'un contrat de travail », à compter de la conclusion du contrat. Le maître négligent ne perd pas seulement le bénéfice du régime de l'apprentissage ; il devient employeur d'un travailleur ordinaire, avec toutes les conséquences en matière de salaire (SMIG et non simple indemnité d'apprentissage), de préavis, de congés et de cotisations. La même présomption joue lorsque le visa a été retiré, à compter du retrait. L'article 22 énumère les diligences de l'autorité de visa. Elle exige un certificat médical de moins de trois mois, établi dans les conditions de l'arrêté prévu à l'article 38 : celui-ci subordonne l'exécution de tout contrat de travail à la constatation de l'aptitude par « un certificat médical délivré par un médecin du travail ou, à défaut, par tout autre médecin » et prévoit les dérogations « en ce qui concerne les travaux légers et salubres autorisés pour les personnes âgées de 15 à moins de 16 ans ». Elle vérifie l'identité, la conformité du contrat, la liberté d'engagement et l'absence de qualification déjà acquise. Elle distribue enfin les quatre exemplaires : un à chaque partie (au représentant de l'apprenti mineur), un conservé par l'Office, un transmis à l'inspecteur du travail du ressort, qui assurera le contrôle de l'exécution (art. 33)." },
      { type: 'filet', titre: "Article 23 du Code du travail", texte: "« A défaut du visa ou en cas de refus de celui-ci, le contrat d'apprentissage est annulable. En cas d'annulation ou de doute sur l'objet du contrat non écrit, les services de l'apprenti sont présumés avoir été prestés en exécution d'un contrat de travail. Lorsqu'il apparaît à l'Inspecteur du Travail que les conditions édictées sur la réglementation de l'apprentissage ne sont plus réunies, le visa peut être retiré par l'Office National de l'Emploi, sur rapport motivé de l'Inspecteur du Travail. Dans ce cas, le contrat cesse de plein droit. »" },
      { type: 'paragraphe', texte: "L'article 23 distingue trois situations. Le contrat non visé ou dont le visa a été refusé est « annulable » : la nullité n'est pas automatique, elle doit être demandée, et elle est relative, c'est-à-dire réservée à la partie protégée, l'apprenti. Le contrat non écrit, ou dont l'objet est douteux, et le contrat annulé produisent la même conséquence : les services sont présumés prestés en exécution d'un contrat de travail. Enfin, le visa accordé peut être retiré en cours d'exécution, sur rapport motivé de l'inspecteur du travail constatant que « les conditions édictées sur la réglementation de l'apprentissage ne sont plus réunies » (par exemple, absence de cours professionnels, travaux dangereux, maître ne dispensant aucune formation) ; le contrat cesse alors de plein droit, et l'article 21 fait basculer les services postérieurs sous la présomption de contrat de travail. L'ensemble de ces règles converge vers un même résultat : l'apprentissage est un régime dérogatoire, accordé à l'employeur qui en respecte les conditions, et refusé à celui qui en abuse. La présomption de contrat de travail est la sanction de droit commun de l'apprentissage irrégulier." },
      { type: 'controle', question: {
        id: 'ctrl-2-6', question: "Un garagiste engage un apprenti de dix-neuf ans par contrat écrit, mais ne soumet jamais le contrat au visa de l'ONEM. Dix-huit mois plus tard, l'apprenti réclame le paiement du SMIG et d'une indemnité de préavis. Est-il fondé ?",
        options: [
          { id: 'a', texte: "Non : le contrat écrit suffit à établir l'apprentissage" },
          { id: 'b', texte: "Oui : à défaut de soumission au visa, ses services sont présumés prestés en exécution d'un contrat de travail depuis la conclusion du contrat" },
          { id: 'c', texte: "Non : seul l'apprenti mineur bénéficie de la présomption" },
          { id: 'd', texte: "Oui, mais seulement pour la période postérieure à la réclamation" },
          { id: 'e', texte: "Non : la demande de visa incombait à l'apprenti" },
        ],
        reponseCorrecte: 'b', articleRef: "Art. 21, al. 3 ; art. 23",
        explication: "La demande de visa incombe au maître. « Tant que le contrat n'a pas été soumis au visa [...], les services de l'apprenti sont présumés être prestés en exécution d'un contrat de travail [...] à la date de la conclusion du contrat. » L'apprenti est donc un travailleur depuis l'origine, avec droit au salaire minimum et au régime de rupture du contrat de travail.",
      } },
    ],
  },
  {
    numero: '2.7',
    titre: "Les obligations du maître et de l'apprenti",
    navLabel: '2.7 Obligations réciproques',
    blocs: [
      { type: 'carte', titre: "Article 24 du Code du travail : les obligations du maître", note: "« L'apprentissage comporte essentiellement pour le maître les obligations suivantes envers l'apprenti : 1) lui enseigner ou lui faire enseigner méthodiquement, progressivement et complètement le métier ou la profession qui fait l'objet du contrat, et mettre à sa disposition les outils et le matériel nécessaires à cet enseignement ; 2) le traiter avec tous les égards voulus, faire respecter les convenances et bonnes mœurs pendant l'exécution du contrat, et veiller à sa sécurité et à sa santé, compte tenu des circonstances et de la nature du travail ; 3) avertir sans retard ses parents ou son tuteur en cas de maladie, d'absence ou de faute grave ou de tout fait de nature à motiver leur intervention ; 4) lui accorder, à l'expiration de chaque période d'un an de services effectifs un congé d'une durée conforme à celle fixée par l'article 141 du présent Code et de lui verser, le cas échéant, l'indemnité prévue au contrat ; 5) lui fournir pendant la durée du contrat, en cas de maladie ou d'accident, les prestations dues aux travailleurs en vertu du présent Code, à l'exception de celles qui sont dues à la famille du travailleur et des prestations relatives au salaire ; 6) lui délivrer, à la fin de l'apprentissage, un certificat de fin d'apprentissage, conforme au modèle fixé par arrêté du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions. »" },
      { type: 'paragraphe', texte: "La première obligation du maître est l'obligation d'enseigner, qualifiée par trois adverbes : « méthodiquement, progressivement et complètement ». Méthodiquement, selon un programme et non au gré des commandes de l'atelier ; progressivement, du simple au complexe ; complètement, jusqu'à la maîtrise de l'ensemble du métier et non d'une seule opération répétitive. Le maître doit en outre fournir les outils et le matériel : un apprenti n'a pas à acheter ses propres instruments de travail. La deuxième obligation est une obligation de respect et de sécurité, qui prolonge l'article 3 du Code : le maître veille « à sa sécurité et à sa santé, compte tenu des circonstances et de la nature du travail », ce qui interdit de confier à l'apprenti, a fortiori mineur, des travaux dangereux. La troisième obligation associe les parents à l'exécution du contrat. La quatrième accorde à l'apprenti un congé annuel calculé selon l'article 141, c'est-à-dire « au moins un jour ouvrable par mois entier de service pour le travailleur âgé de plus de dix-huit ans » et « au moins un jour ouvrable et demi par mois entier de service pour le travailleur âgé de moins de dix-huit ans » : l'apprenti mineur a donc droit à dix-huit jours ouvrables par an, l'apprenti majeur à douze. La cinquième obligation étend à l'apprenti les prestations dues aux travailleurs en cas de maladie ou d'accident (soins de santé, hospitalisation), à l'exclusion des prestations familiales et des prestations relatives au salaire. La sixième, enfin, est la délivrance d'un certificat de fin d'apprentissage conforme au modèle réglementaire, qui atteste la qualification acquise et permet à l'ancien apprenti de se prévaloir de son métier auprès d'autres employeurs." },
      { type: 'filet', titre: "Article 25 du Code du travail", texte: "« Le maître a l'obligation de rémunérer l'apprenti dans les conditions fixées par arrêté du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions, pris après avis du Conseil National du Travail. Cette rémunération prend la forme d'une indemnité qui devra être majorée au fur et à mesure des années d'apprentissage. Toutes les obligations et garanties prévues par le présent Code en matière de salaire s'attachent à cette rémunération. »" },
      { type: 'paragraphe', texte: "L'article 25 tranche une question que l'article 20 avait laissée ouverte : l'apprenti doit être rémunéré. La rémunération prend la forme d'une indemnité, dont les conditions sont fixées par arrêté ministériel après avis du Conseil National du Travail, et qui doit être « majorée au fur et à mesure des années d'apprentissage », progression qui reflète l'accroissement de la valeur productive de l'apprenti. Surtout, « toutes les obligations et garanties prévues par le présent Code en matière de salaire s'attachent à cette rémunération » : périodicité du paiement, paiement en espèces, protection contre les retenues abusives, privilège du salaire, prescription (Titre V, chapitre 5). L'indemnité d'apprentissage n'est donc pas une libéralité que le maître pourrait retenir à titre de sanction ; c'est une créance protégée comme un salaire. Le montant de l'indemnité peut être inférieur au SMIG, précisément parce que l'apprenti reçoit en outre une formation ; mais si la formation fait défaut, la présomption de contrat de travail rétablit le droit au salaire minimum." },
      { type: 'carte', titre: "Article 26 du Code du travail : les obligations de l'apprenti", note: "« L'apprentissage comporte essentiellement pour l'apprenti les obligations suivantes : 1) se conformer aux ordres du maître d'apprentissage ou de son préposé ; 2) exécuter les travaux qui lui sont confiés aux conditions convenues et, d'une manière générale, aider le maître d'apprentissage ou son préposé dans la mesure de ses aptitudes et de ses forces ; 3) observer le respect des convenances et des bonnes mœurs pendant l'exécution du contrat ; 4) restituer en bon état les outils, marchandises, produits ou tout objet qui lui sont confiés par le maître d'apprentissage, sauf détériorations et usures dues à l'usage normal de la chose ou perte par cas fortuit ; 5) s'abstenir de tout ce qui pourrait nuire aux intérêts du maître d'apprentissage, à sa propre sécurité ou à celle de ses compagnons et garder les secrets de fabrication ou d'affaires dont il a connaissance à l'occasion de son apprentissage ; 6) se soumettre aux examens médicaux imposés par le maître d'apprentissage, ainsi qu'aux épreuves d'évaluation en vue de contrôle de sa formation professionnelle. »" },
      { type: 'paragraphe', texte: "Les obligations de l'apprenti sont le miroir de celles du maître. L'obéissance aux ordres (point 1) et l'exécution des travaux confiés (point 2) traduisent le lien de subordination propre à l'apprentissage, tempéré par la mesure « de ses aptitudes et de ses forces » : le maître ne peut exiger d'un apprenti ce qu'exigerait d'un ouvrier confirmé. L'obligation de restitution des outils et marchandises (point 4) est limitée aux détériorations anormales : l'usure normale et le cas fortuit restent à la charge du maître, ce qui exclut la pratique consistant à retenir sur l'indemnité le prix des outils cassés dans l'exercice normal du métier. L'obligation de loyauté et de secret (point 5) protège le fonds de commerce du maître : l'apprenti coiffeur ne peut détourner la clientèle, l'apprenti pâtissier ne peut divulguer les recettes. L'obligation de se soumettre aux examens médicaux et aux épreuves d'évaluation (point 6) fait le lien avec la mission de certification de l'INPP (art. 13, point b)." },
      { type: 'filet', titre: "Article 27 du Code du travail", texte: "« Il pourra être prévu au contrat d'apprentissage que l'apprenti s'engage, après achèvement de l'apprentissage, à exercer son activité professionnelle pour le compte de son ancien maître pendant une période qui ne peut excéder deux ans. L'inobservation de cet engagement par l'une des parties entraîne, sous réserve des dommages-intérêts, la prestation d'un préavis ou à défaut le versement d'une indemnité compensatoire de préavis calculée conformément aux dispositions de l'article 63 du présent Code. »" },
      { type: 'paragraphe', texte: "L'article 27 organise une clause de fidélité. Le maître qui a investi dans la formation d'un apprenti peut craindre de le voir partir, dès qualifié, chez un concurrent. Le Code lui permet de stipuler que l'apprenti travaillera pour lui, après l'apprentissage, « pendant une période qui ne peut excéder deux ans ». La clause est facultative (« il pourra être prévu »), plafonnée à deux ans, et réciproque : « l'inobservation de cet engagement par l'une des parties » est sanctionnée, ce qui signifie que le maître qui refuserait d'engager l'ancien apprenti serait tenu comme celui-ci. La relation postérieure à l'apprentissage est un contrat de travail ordinaire, et la sanction de la rupture anticipée est celle du contrat de travail : préavis ou indemnité compensatoire calculée « conformément aux dispositions de l'article 63 », c'est-à-dire égale à « la rémunération et aux avantages de toute nature dont aurait bénéficié le travailleur durant le délai de préavis qui n'a pas été effectivement respecté », sans préjudice de dommages-intérêts. Cette clause ne doit pas être confondue avec une clause de non-concurrence : elle oblige à travailler pour l'ancien maître, elle n'interdit pas, à son terme, de s'établir à son compte ou chez un concurrent." },
      { type: 'tableau', tableau: { entetes: ["Obligation", "Maître (art. 24-25)", "Apprenti (art. 26-27)"], lignes: [
        ["Prestation principale", "Enseigner méthodiquement, progressivement et complètement ; fournir outils et matériel", "Se conformer aux ordres ; exécuter les travaux confiés selon ses aptitudes et ses forces"],
        ["Rémunération", "Indemnité fixée par arrêté, majorée chaque année, protégée comme un salaire", "Sans objet"],
        ["Sécurité et santé", "Veiller à la sécurité et à la santé ; prestations de maladie et d'accident (hors famille et salaire)", "Ne pas nuire à sa propre sécurité ni à celle des compagnons ; examens médicaux"],
        ["Loyauté", "Égards, convenances et bonnes mœurs ; avertir les parents", "Convenances et bonnes mœurs ; secret des affaires ; restitution des outils"],
        ["Congé", "Congé annuel selon l'article 141 après chaque année de services effectifs", "Sans objet"],
        ["Fin de l'apprentissage", "Certificat de fin d'apprentissage conforme au modèle réglementaire", "Clause de fidélité facultative de deux ans au plus, sanctionnée par le préavis de l'article 63"],
      ] } },
    ],
  },
  {
    numero: '2.8',
    titre: "Suspension, fin et résiliation du contrat d'apprentissage",
    navLabel: '2.8 Suspension et fin',
    blocs: [
      { type: 'filet', titre: "Article 28 du Code du travail", texte: "« Le contrat d'apprentissage est suspendu pendant la durée de l'incapacité de travail de l'apprenti résultant de maladie ou d'accident. Le maître d'apprentissage a toutefois la faculté de résilier le contrat lorsque l'incapacité de travail a duré six mois ou lorsque la maladie ou l'accident fait présumer que l'apprenti ne pourra remplir ses obligations pendant une période continue de six mois ininterrompus hormis le cas d'accident du travail et de maladie professionnelle. »" },
      { type: 'paragraphe', texte: "La maladie ou l'accident de l'apprenti suspend le contrat : les obligations réciproques sont mises en sommeil, mais le lien subsiste, et l'apprenti conserve le bénéfice des prestations de l'article 24, point 5. La suspension n'est pas indéfinie : au bout de six mois d'incapacité, ou dès qu'un pronostic médical fait présumer une incapacité de six mois ininterrompus, le maître peut résilier. Cette faculté est exclue en cas d'accident du travail ou de maladie professionnelle, c'est-à-dire lorsque l'incapacité trouve sa cause dans l'apprentissage lui-même : le maître ne peut pas se défaire d'un apprenti blessé à son service. On reconnaît ici le régime de la suspension du contrat de travail pour incapacité, étudié au chapitre 3, transposé à l'apprentissage." },
      { type: 'carte', titre: "Article 29 du Code du travail : la fin de plein droit", note: "« Le contrat d'apprentissage prend fin de plein droit avant son terme : a) par la mort du maître ou de l'apprenti ; b) par l'appel ou le rappel sous le drapeau de l'apprenti ou du maître ; c) par la condamnation du maître à une peine de servitude pénale supérieure à trois mois sans sursis ; d) pour les filles mineures apprenties habitant chez le maître, en cas de divorce de ce dernier, du décès de l'épouse du maître ou de toute femme de la famille qui dirigeait la maison à l'époque de la conclusion du contrat. »" },
      { type: 'paragraphe', texte: "Le contrat d'apprentissage est conclu en considération de la personne, du maître comme de l'apprenti : c'est un contrat intuitu personae. C'est pourquoi la mort de l'une ou l'autre partie y met fin de plein droit, alors que le décès de l'employeur ne met pas fin, en principe, au contrat de travail, qui se poursuit avec les héritiers ou l'entreprise substituée. L'appel sous le drapeau, la condamnation du maître à plus de trois mois de servitude pénale sans sursis (qui ruine la condition de bonne vie et mœurs de l'article 18) et, pour les jeunes filles mineures logées chez le maître, la disparition de la femme qui dirigeait la maison (divorce, décès de l'épouse ou de toute femme de la famille) sont les autres causes de fin de plein droit. Cette dernière cause prolonge la règle de l'article 18, alinéa 2 : la présence d'une femme de la famille est la condition même du logement d'une apprentie mineure, et sa disparition fait cesser le contrat sans qu'aucune faute soit imputable à quiconque." },
      { type: 'carte', titre: "Article 30 du Code du travail : la résiliation pour cause", note: "« Tout contrat d'apprentissage peut être résilié à la demande des parties pour les causes ci-après : a) si l'une des parties manquait aux stipulations du contrat ; b) pour cause d'infraction grave ou habituelle aux prescriptions des articles 24 et 26 du présent Code ou des autres dispositions légales ou réglementaires concernant les conditions de travail des apprentis ; c) lorsque le maître transporte sa résidence hors de l'entité administrative dans laquelle il habitait et exerçait son activité lors de la conclusion du contrat ; d) lorsque le maître ou l'apprenti encourt une condamnation à une peine de servitude pénale principale de plus de deux mois ; e) le mariage de l'apprenti ou éventuellement l'acquisition de la qualité de chef de famille à la suite du décès de son père. Dans ce cas, la résiliation du contrat ne peut intervenir qu'à la demande de l'apprenti lui-même. »" },
      { type: 'paragraphe', texte: "À la différence de la fin de plein droit, la résiliation de l'article 30 suppose une demande et une cause. Les causes a) et b) sont des causes fautives : manquement aux stipulations du contrat, infraction grave ou habituelle aux obligations légales des articles 24 et 26 ou aux règles sur les conditions de travail des apprentis. Le maître qui ne dispense aucune formation, l'apprenti qui s'absente habituellement ou détourne la clientèle en relèvent. Les causes c) et d) sont des causes objectives : le déménagement du maître hors de l'entité administrative, qui rendrait l'apprentissage impossible pour un apprenti attaché à son lieu de vie, et la condamnation de l'une ou l'autre partie à plus de deux mois de servitude pénale principale. La cause e) est propre à l'apprenti et ne peut être invoquée que par lui : son mariage ou son accession à la qualité de chef de famille après le décès de son père, événements qui lui imposent de subvenir aux besoins d'un ménage et donc de gagner un véritable salaire." },
      { type: 'filet', titre: "Article 31 du Code du travail", texte: "« Lorsque l'apprenti est mineur, et sans préjudice à l'exercice de l'autorité parentale ou tutélaire, toute résiliation du contrat d'apprentissage à l'initiative du maître est soumise à la condition suspensive de son approbation par l'Inspecteur du Travail du ressort. La demande d'approbation est adressée à l'Inspecteur du Travail par lettre recommandée ou par cahier de transmission. L'Inspecteur du Travail doit notifier sa décision dans le mois à partir du jour où le maître lui a fait connaître la mesure envisagée ; à défaut, il est censé l'approuver. La décision de l'Inspecteur du Travail est susceptible d'un recours hiérarchique ou judiciaire dans les conditions fixées par arrêté du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions, pris après avis du Conseil National du Travail. »" },
      { type: 'paragraphe', texte: "L'article 31 institue une protection procédurale renforcée de l'apprenti mineur : la résiliation à l'initiative du maître est soumise « à la condition suspensive de son approbation par l'Inspecteur du Travail ». La résiliation ne produit d'effet qu'une fois approuvée ; jusque-là, le contrat continue. L'inspecteur dispose d'un mois pour se prononcer, à compter de la notification par lettre recommandée ou par cahier de transmission ; son silence vaut approbation, règle d'approbation tacite qui évite que l'inertie administrative ne paralyse le maître. La décision est susceptible de recours hiérarchique (devant l'autorité supérieure de l'inspection) ou judiciaire. Ce mécanisme rappelle celui qui protège les délégués du personnel contre le licenciement (chapitre 8) : dans les deux cas, le Code interpose l'inspection du travail entre l'employeur et une catégorie de personnes vulnérables." },
      { type: 'paragraphe', texte: "L'article 32 fixe enfin les délais de recevabilité des demandes de résiliation. Pour les causes a), b) et d) de l'article 30, les demandes « ne sont recevables par l'Inspecteur du Travail que dans les formes et délais fixés à l'article 72 » : cet article, relatif à la faute lourde, impose de notifier par écrit la décision « dans les quinze jours ouvrables au plus tard après avoir eu connaissance des faits », par lettre recommandée, remise contre accusé de réception ou, en cas de refus, en présence de deux témoins lettrés. Le maître qui découvre une faute grave de l'apprenti mineur doit donc agir dans les quinze jours ouvrables, sous peine de forclusion. Pour les causes c) et e), le délai est de trois mois. Ces délais ont une double fonction : ils obligent la partie qui invoque une cause de résiliation à réagir promptement, et ils protègent l'autre partie contre la menace indéfinie d'une rupture fondée sur des faits anciens." },
      { type: 'tableau', tableau: { entetes: ['Événement', 'Effet', 'Formalités et délais'], lignes: [
        ["Maladie ou accident de l'apprenti", "Suspension (art. 28)", "Résiliation possible après six mois d'incapacité, sauf accident du travail ou maladie professionnelle"],
        ["Mort, appel sous le drapeau, condamnation du maître à plus de trois mois sans sursis, perte de la femme dirigeant la maison (apprentie mineure logée)", "Fin de plein droit (art. 29)", "Aucune, sauf information de l'inspecteur et de l'ONEM (art. 33)"],
        ["Manquement contractuel, infraction grave ou habituelle, condamnation à plus de deux mois", "Résiliation pour cause (art. 30, a, b, d)", "Formes et délai de l'article 72 : notification écrite dans les quinze jours ouvrables"],
        ["Déménagement du maître, mariage ou qualité de chef de famille de l'apprenti", "Résiliation pour cause (art. 30, c, e)", "Recevable pendant trois mois ; la cause e) n'est ouverte qu'à l'apprenti"],
        ["Résiliation par le maître d'un apprenti mineur", "Condition suspensive (art. 31)", "Approbation de l'inspecteur du travail dans le mois ; silence vaut approbation ; recours hiérarchique ou judiciaire"],
      ] } },
    ],
  },
  {
    numero: '2.9',
    titre: "Contrôle, assimilation aux travailleurs et limitation des effectifs d'apprentis",
    navLabel: '2.9 Contrôle et assimilation',
    blocs: [
      { type: 'filet', titre: "Article 33 du Code du travail", texte: "« L'Inspecteur du Travail du ressort est chargé du contrôle de l'exécution du contrat d'apprentissage ; il peut se faire assister d'un technicien pour le contrôle de l'enseignement donné à l'apprenti dans l'établissement. Toute cessation de contrat d'apprentissage doit être portée à la connaissance de l'Inspecteur du Travail et de l'Office National de l'Emploi. »" },
      { type: 'paragraphe', texte: "Le contrôle de l'apprentissage repose sur deux institutions. L'inspecteur du travail du ressort, destinataire du quatrième exemplaire du contrat (art. 22, d), contrôle son exécution ; il peut se faire assister d'un technicien du métier pour apprécier la qualité de l'enseignement, ce qu'un juriste n'est pas toujours en mesure de faire. C'est sur son rapport motivé que l'Office National de l'Emploi peut retirer le visa (art. 23). L'inspecteur approuve en outre la résiliation par le maître du contrat d'un apprenti mineur (art. 31) et reçoit les demandes de résiliation pour cause (art. 32). L'Office National de l'Emploi, pour sa part, vise le contrat, en conserve un exemplaire et doit être informé de toute cessation, comme l'inspecteur. Cette double information permet à l'administration de tenir la statistique de l'apprentissage et de vérifier que la cessation n'est pas un moyen de contourner les protections du Titre III." },
      { type: 'filet', titre: "Article 34 du Code du travail", texte: "« Les apprentis sont assimilés aux travailleurs et bénéficient de toutes les autres dispositions du présent Code qui ne sont pas contraires aux dispositions particulières du présent Titre. »" },
      { type: 'paragraphe', texte: "L'article 34 est la disposition la plus importante du Titre III pour la protection de l'apprenti. Il pose un principe d'assimilation : l'apprenti est un travailleur, et l'ensemble du Code lui est applicable, sauf les dispositions particulières du Titre III qui y dérogent. Concrètement, l'apprenti bénéficie des règles sur la durée du travail, le repos hebdomadaire et les jours fériés (Titre VI, chapitre 6), sur la santé et la sécurité au travail et le service médical d'entreprise (Titres VII et VIII, chapitre 7), sur la protection de la rémunération (Titre V, par renvoi exprès de l'article 25), sur la représentation des travailleurs et les conventions collectives (Titre XII, chapitre 8), sur le règlement des litiges devant l'inspecteur du travail et le tribunal du travail (Titre XIII, chapitre 9). Il ne bénéficie pas, en revanche, des dispositions incompatibles avec la nature du contrat : le régime de la durée du contrat de travail (CDD et CDI), le préavis de l'article 64 et les dommages-intérêts de l'article 63 pour la rupture du contrat d'apprentissage lui-même, remplacés par les articles 28 à 32, ou le salaire minimum, remplacé par l'indemnité d'apprentissage. L'assimilation joue aussi au regard de la sécurité sociale : l'apprenti est assujetti au régime général au titre des risques professionnels, et le maître doit le déclarer à la CNSS." },
      { type: 'filet', titre: "Article 35 du Code du travail", texte: "« Des arrêtés du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions, pris après avis du Conseil National du Travail, peuvent déterminer les catégories d'entreprises dans lesquelles est imposé un pourcentage maximum d'apprentis par rapport au nombre des travailleurs. Des arrêtés du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions peuvent limiter l'effectif des apprentis ou le droit de former des apprentis dans les établissements dans lesquels il a été constaté une formation professionnelle insuffisante. »" },
      { type: 'paragraphe', texte: "L'article 35 arme le ministre contre deux abus. Le premier est le remplacement de la main-d'œuvre salariée par des apprentis : une entreprise qui compterait dix apprentis pour deux travailleurs n'organise pas une formation, elle exploite une main-d'œuvre à bas coût. Un arrêté, pris après avis du Conseil National du Travail, peut fixer par catégorie d'entreprises « un pourcentage maximum d'apprentis par rapport au nombre des travailleurs ». Le second abus est la formation insuffisante : dans les établissements où elle a été constatée, un arrêté peut limiter l'effectif des apprentis ou retirer le droit d'en former. Ce second arrêté ne requiert pas l'avis du Conseil National du Travail, car il s'agit d'une mesure individuelle de police administrative, fondée sur un constat de l'inspection, et non d'une règle générale. Ces dispositions montrent que le droit de former des apprentis n'est pas une liberté absolue de l'employeur, mais une faculté encadrée, dont l'exercice est subordonné à la qualité de la formation dispensée." },
      { type: 'controle', question: {
        id: 'ctrl-2-9', question: "Un apprenti majeur, dont le contrat est régulièrement visé, se voit imposer cinquante-cinq heures de travail par semaine « parce qu'il n'est pas un travailleur ». Que répondre au maître ?",
        options: [
          { id: 'a', texte: "Il a raison : seul le Titre III s'applique aux apprentis" },
          { id: 'b', texte: "Il a tort : les apprentis sont assimilés aux travailleurs et bénéficient de toutes les dispositions du Code non contraires au Titre III, dont la durée légale du travail" },
          { id: 'c', texte: "Il a raison, sauf pour les apprentis mineurs" },
          { id: 'd', texte: "Il a tort, mais seulement si l'apprenti a signé une convention collective" },
          { id: 'e', texte: "Il a raison, l'apprenti n'étant pas rémunéré" },
        ],
        reponseCorrecte: 'b', articleRef: "Art. 34",
        explication: "« Les apprentis sont assimilés aux travailleurs et bénéficient de toutes les autres dispositions du présent Code qui ne sont pas contraires aux dispositions particulières du présent Titre. » Les règles sur la durée du travail (Titre VI) leur sont donc applicables, et l'apprenti est en outre rémunéré par une indemnité protégée comme un salaire (art. 25).",
      } },
    ],
  },
  {
    numero: '2.10',
    titre: "Enjeux contemporains : formation, emploi des jeunes et actualités 2025-2026",
    navLabel: '2.10 Enjeux et actualités',
    blocs: [
      { type: 'paragraphe', texte: "Les Titres II et III du Code doivent être lus à la lumière de la situation de l'emploi en RDC. L'enquête sur les conditions de vie des ménages conduite par l'Institut national de la statistique en 2024-2025 établit un taux d'emploi moyen de 55,9 % à l'échelle nationale, avec une prépondérance de l'agriculture (45,7 % des actifs occupés) et du commerce (14 %), suivis de l'éducation et de la santé (8,3 %). L'essentiel de ces emplois relève de l'économie informelle, où la formation professionnelle se transmet par l'apprentissage traditionnel, sans contrat écrit, sans visa et sans certificat. Le chômage et le sous-emploi des jeunes, particulièrement élevés dans les grandes villes, ont conduit les pouvoirs publics à faire de la formation professionnelle un axe de l'objectif de création de six millions d'emplois affiché par le Gouvernement. Dans ce contexte, l'apprentissage formalisé du Titre III et les services de l'INPP constituent des outils juridiques disponibles mais sous-utilisés, dont la promotion dépend de l'effectivité du contrôle et de l'attractivité du régime pour les employeurs." },
      { type: 'paragraphe', texte: "Trois évolutions récentes concernent directement les matières de ce chapitre. La première est financière : l'arrêté interministériel du 24 septembre 2025 a relevé le taux de la cotisation INPP pour la première fois depuis 2006 (section 2.4). Les employeurs privés de moins de cinquante travailleurs, majoritaires, voient leur cotisation passer de 3 % à 3,5 % de la masse des rémunérations ; ceux de plus de trois cents travailleurs, de 1 % à 2 %, soit un doublement. Cette hausse s'ajoute au relèvement du SMIG à 21 500 francs par jour depuis janvier 2026 (décret n°25/22), qui augmente mécaniquement l'assiette des cotisations, et à l'entrée en vigueur du nouveau tarif des cotisations de sécurité sociale depuis 2019. Le coût du travail formel s'en trouve accru, ce que les organisations d'employeurs ont relevé lors des débats sur l'application progressive du SMIG. Elle renforce en contrepartie la capacité de l'Institut à offrir des formations aux entreprises cotisantes." },
      { type: 'paragraphe', texte: "La deuxième évolution est institutionnelle : la structuration du ministère de la Formation professionnelle et des Métiers (cadre organique du 16 avril 2026, formation à l'approche par compétences du 25 février 2026, annuaire des filières prioritaires validé en décembre 2025, passerelles avec l'Éducation nationale pour 2026-2027) et le renforcement des partenariats de l'INPP (protocole avec l'ANEP du 23 décembre 2025, contrat-programme de performance 2026, dispositifs mobiles annoncés pour avril 2026). Ces développements ne modifient pas les articles 8 à 35, mais ils en conditionnent l'application : l'obligation de formation de l'article 8 est d'autant plus exigible que l'offre de formation existe, et le visa des contrats d'apprentissage d'autant plus contrôlable que l'administration de l'emploi se modernise." },
      { type: 'paragraphe', texte: "La troisième évolution est réglementaire et touche l'Office National de l'Emploi, autorité de visa des contrats d'apprentissage : l'arrêté du ministre de l'Emploi et du Travail du 9 octobre 2025 soumet toute offre d'emploi à un visa préalable de l'ONEM avant publication, sous peine d'amende administrative. Cette mesure, étudiée au chapitre 8, s'inscrit dans une politique de formalisation du marché du travail dont l'apprentissage est l'un des maillons : un employeur qui recrute des apprentis par voie d'annonce doit désormais faire viser l'annonce, puis le contrat." },
      { type: 'tableau', tableau: { entetes: ['Texte ou fait', 'Date', 'Portée pour ce chapitre'], lignes: [
        ["Arrêté interministériel fixant le taux de la cotisation INPP (4 %, 3,5 %, 3 %, 2 %)", "24 septembre 2025", "Abroge l'arrêté du 14 février 2006 ; en vigueur à la signature"],
        ["Protocole d'accord ANEP-INPP", "23 décembre 2025", "Adaptation de l'offre de formation aux besoins des entreprises du portefeuille"],
        ["Semaine de la formation professionnelle (annuaire des filières prioritaires, avec Enabel)", "15 au 19 décembre 2025", "Politique sectorielle de la formation"],
        ["Conférence sino-congolaise sur la formation professionnelle", "22 décembre 2025", "Dispositifs de formation mobiles annoncés pour avril 2026"],
        ["Formation de 200 agents à l'approche par compétences", "25 février 2026", "Renforcement des capacités du ministère de la Formation professionnelle"],
        ["Cadre organique du Secrétariat général de la Formation professionnelle", "16 avril 2026", "Gouvernance administrative du secteur"],
        ["Arrêté du ministre de l'Emploi et du Travail sur le visa ONEM des offres d'emploi", "9 octobre 2025", "Formalisation du recrutement, y compris des apprentis"],
      ] } },
      { type: 'paragraphe', texte: "Ces évolutions invitent enfin à une réflexion prospective. Le régime de l'apprentissage du Titre III, hérité pour l'essentiel du code de 1967, repose sur la figure du maître artisan et de l'apprenti mineur logé chez lui ; il ne connaît ni l'apprentissage en alternance dans les grandes entreprises, ni la formation duale associant un centre de formation et une entreprise, ni la reconnaissance des acquis de l'expérience pour les travailleurs de l'économie informelle. Les propositions de réforme du Code déposées en 2025 et 2026 (chapitre 1, section 1.10) ne traitent pas spécifiquement de l'apprentissage, mais la modernisation de la formation professionnelle engagée par les pouvoirs publics rendra sans doute nécessaire une actualisation de ce Titre. L'étudiant retiendra que, dans l'état du droit positif, tout apprentissage doit satisfaire aux conditions des articles 18 à 23 pour échapper à la présomption de contrat de travail, et que cette présomption est le meilleur allié de l'apprenti exploité." },
    ],
  },
]

